family_rows=['## Family-level descriptive coverage','Three tasks per family remain a small source-group sample. Context,source length and subtask differ; these rows describe demand and are not policy comparisons.','| Family | Groups / prior exposed | Complete windows | Main entries | Local / CPU / mapped % (entry-weighted) | Operating min |','|---|---:|---:|---:|---|---:|']
for family in sorted(set(x['family'] for x in tasks)):
 group=[x for x in tasks if x['family']==family];entries=sum(x['main_entries'] for x in group);shares=[sum(x['main_entries']*x[k]/100 for x in group)/entries*100 for k in ['local_pct','cpu_pct','mapped_pct']]
 family_rows.append(f"| {family} | {len(group)} / {sum(x['prior_exposure'] for x in group)} | {sum(x['windows'] for x in group)} | {entries:,} | {' / '.join(f'{v:.2f}' for v in shares)} | {sum(x['total_operating_s'] for x in group)/60:.2f} |")
